  "Fluoroquinolone Antibiotic + Antacid": { hi: "एंटीबायोटिक + एंटासिड", es: "Antibiótico fluoroquinolona + Antiácido", fr: "Antibiotique fluoroquinolone + Antiacide", de: "Fluorchinolon-Antibiotikum + Antazidum", zh: "氟喹诺酮抗生素 + 抑酸药", ko: "플루오로퀴놀론 항생제 + 제산제" },
  "BP Medicine + Painkiller": { hi: "बीपी दवा + दर्द निवारक", es: "Medicamento de presión + Analgésico", fr: "Médicament tension + Anti-douleur", de: "Blutdruckmedikament + Schmerzmittel", zh: "降压药 + 止痛药", ko: "혈압약 + 진통제" },
