  "Need 2 reports": { hi: "2 रिपोर्ट चाहिए", es: "Se necesitan 2 informes", fr: "Besoin de 2 rapports", de: "2 Berichte erforderlich", zh: "需要 2 份报告", ko: "2개의 보고서 필요" },
