  "Log Vitals Now": { hi: "अभी जांच करें", es: "Registrar signos vitales ahora", fr: "Enregistrer les constantes maintenant", de: "Vitalwerte jetzt eintragen", zh: "立即记录体征", ko: "지금 바이탈 기록하기" },
